%[text] # Single-story frame with a nonlinear viscous damper
%[text] Reproduce a one-storey OpenSees Tcl benchmark in MATLAB. Steel4 fiber
%[text] columns provide frame nonlinearity and a `ViscousDamper` material drives
%[text] the diagonal link. The final plots compare MATLAB and Tcl recorder data.
%[text] Units are mm, kN, and s.
clear; clc; close all;
%%
%[text] ## 1. Create OpenSeesMatlab interfaces

opsMAT = OpenSeesMatlab();
ops  = opsMAT.opensees;
post = opsMAT.post;
vis  = opsMAT.vis;

figDir = 'figures';
if ~exist(figDir, 'dir')
    mkdir(figDir);
end
%%
%[text] ## 2. Initialize OpenSees model
tic

ops.wipe();
ops.model('BasicBuilder', '-ndm', 2, '-ndf', 3);
%%
%[text] ## 3. Geometry and nodes
L = 5000.0;   % bay width, mm
h = 3000.0;   % story height, mm

ops.node(1, 0.0, 0.0);
ops.node(2, L,   0.0);
ops.node(3, 0.0, h);
ops.node(4, L,   h);
%%
%[text] ## 4. Boundary conditions and floor constraint
ops.fix(1, 1, 1, 1);
ops.fix(2, 1, 1, 1);

% equalDOF retainedNode constrainedNode dofs
ops.equalDOF(3, 4, 2, 3);
%%
%[text] ## 5. Mass
W = 1000.0;     % kN
g = 9810.0;     % mm/sec^2
m = W / g;      % kN-sec^2/mm

piVal = acos(-1.0);

ops.mass(3, 0.5*m, 0.0, 0.0);
ops.mass(4, 0.5*m, 0.0, 0.0);
%%
%[text] ## 6. Nonlinear steel material for columns
FyCol = 0.345;      % kN/mm^2
E0    = 200.0;      % kN/mm^2
b     = 0.01;

R0  = 18.0;
cR1 = 0.925;
cR2 = 0.15;
FuCol = 1.20 * FyCol;
RuCol = 20.0;

matColSteel = 1;

ops.uniaxialMaterial('Steel4', matColSteel, FyCol, E0, ...
    '-kin', b, R0, cR1, cR2, '-ult', FuCol, RuCol);
%%
%[text] ## 7. Fiber section for nonlinear steel columns
%[text] This section is written explicitly to match the Tcl section Fiber block.
secCol = 1;

% Column H-section dimensions, mm
dCol  = 300.0;
twCol = 8.0;
bfCol = 220.0;
tfCol = 14.0;

% Fiber discretization, same as Tcl
nfdw = 16;
nftw = 2;
nfbf = 12;
nftf = 2;

yTop   =  0.5 * dCol;
yBot   = -0.5 * dCol;
zLeft  = -0.5 * bfCol;
zRight =  0.5 * bfCol;
zWebL  = -0.5 * twCol;
zWebR  =  0.5 * twCol;

yTopFlangeBot =  0.5 * dCol - tfCol;
yBotFlangeTop = -0.5 * dCol + tfCol;

ops.section('Fiber', secCol);

% Top flange
ops.patch('rect', matColSteel, nftf, nfbf, ...
    yTopFlangeBot, zLeft, ...
    yTop,          zRight);

% Web
ops.patch('rect', matColSteel, nfdw, nftw, ...
    yBotFlangeTop, zWebL, ...
    yTopFlangeBot, zWebR);

% Bottom flange
ops.patch('rect', matColSteel, nftf, nfbf, ...
    yBot,          zLeft, ...
    yBotFlangeTop, zRight);
%%
%[text] ## 8. Elastic roof beam properties
%[text] Same as Tcl version.
EBeam = 200.0;       % kN/mm^2

dBeam  = 500.0;      % mm
twBeam = 12.0;       % mm
bfBeam = 300.0;      % mm
tfBeam = 20.0;       % mm

ABeam = 2.0 * bfBeam * tfBeam + twBeam * (dBeam - 2.0 * tfBeam);

IBeam = ...
    (twBeam * (dBeam - 2.0 * tfBeam)^3) / 12.0 + ...
    2.0 * ( ...
        (bfBeam * tfBeam^3) / 12.0 + ...
        bfBeam * tfBeam * ((dBeam - tfBeam) / 2.0)^2 );

beamStiffnessFactor = 10.0;

ABeamEff = beamStiffnessFactor * ABeam;
IBeamEff = beamStiffnessFactor * IBeam;
%%
%[text] ## 9. Nonlinear viscous damper
Kd = 25.0;
Cd = 20.7452;
ad = 0.35;

matDamper = 10;

ops.uniaxialMaterial('ViscousDamper', matDamper, Kd, Cd, ad); %[output:605c0b0c]
%%
%[text] ## 10. Geometric transformation and beam integration
TransfTag = 1;
ops.geomTransf('Linear', TransfTag);

numIntPts = 5;
beamIntCol = 1;

ops.beamIntegration('Lobatto', beamIntCol, secCol, numIntPts);
%%
%[text] ## 11. Elements
%[text] Nonlinear steel columns
ops.element('forceBeamColumn', 1, 1, 3, TransfTag, beamIntCol);
ops.element('forceBeamColumn', 2, 2, 4, TransfTag, beamIntCol);

% Elastic roof beam
ops.element('elasticBeamColumn', 3, 3, 4, ABeamEff, EBeam, IBeamEff, TransfTag);

% Nonlinear viscous damper
ops.element('twoNodeLink', 4, 1, 4, '-mat', matDamper, '-dir', 1);

disp('Nonlinear steel-column frame with elastic roof beam built.'); %[output:2f58a43f]
%%
%[text] ## 12. Ground-motion input
gmFile = 'TakY.th';
dtGM = 0.01;

if ~exist(gmFile, 'file')
    warning('Ground-motion file "%s" was not found in the current directory.', gmFile);
end

groundMotion = load(gmFile);
recordPeak = max(abs(groundMotion(:)));
scaleFactor = 1.00 * g / recordPeak;

ops.timeSeries('Path', 1, '-dt', dtGM, '-filePath', gmFile, '-factor', scaleFactor);
%%
%[text] ## 13. Recorders
outdir = "Output";
if ~isfolder(outdir)
    mkdir(outdir);
end

ops.recorder('Node', '-file', char(fullfile(outdir, 'Disp.out')), ...
    '-time', '-node', 4, '-dof', 1, 'disp');

ops.recorder('Node', '-file', char(fullfile(outdir, 'Acc.out')), ...
    '-timeSeries', 1, '-time', '-node', 4, '-dof', 1, 'accel');

ops.recorder('Node', '-file', char(fullfile(outdir, 'Base.out')), ...
    '-time', '-node', 1, 2, '-dof', 1, 'reaction');

ops.recorder('Node', '-file', char(fullfile(outdir, 'NBase.out')), ...
    '-time', '-node', 1, 2, '-dof', 2, 'reaction');

ops.recorder('Element', '-file', char(fullfile(outdir, 'Damperdisp.out')), ...
    '-time', '-ele', 4, 'deformations');

ops.recorder('Element', '-file', char(fullfile(outdir, 'Damperforce.out')), ...
    '-time', '-ele', 4, 'localForce');

ops.recorder('Element', '-file', char(fullfile(outdir, 'Dampergbforce.out')), ...
    '-time', '-ele', 4, '-dof', 1, 'force');

% Match Tcl:
% recorder Element -file $Output/Frameforce.out -time -ele 1 2 force
ops.recorder('Element', '-file', char(fullfile(outdir, 'Frameforce.out')), ...
    '-time', '-ele', 1, 2, 'force');

% Optional section recorders, consistent with Tcl
ops.recorder('Element', '-file', char(fullfile(outdir, 'Col1_sec1_force.out')), ...
    '-time', '-ele', 1, 'section', 1, 'force');

ops.recorder('Element', '-file', char(fullfile(outdir, 'Col1_sec1_defo.out')), ...
    '-time', '-ele', 1, 'section', 1, 'deformation');

ops.recorder('Element', '-file', char(fullfile(outdir, 'Col2_sec1_force.out')), ...
    '-time', '-ele', 2, 'section', 1, 'force');

ops.recorder('Element', '-file', char(fullfile(outdir, 'Col2_sec1_defo.out')), ...
    '-time', '-ele', 2, 'section', 1, 'deformation');
%%
%[text] ## 14. OpenSeesMatlab response database
post.createODB("myODB", interpolateBeamDisp=11); %[output:8c9266a5]
%%
%[text] ## 15. Eigenvalue analysis and Rayleigh damping
lambda = ops.eigen(1);
freq = sqrt(lambda(1));
period = 2.0*piVal/freq;

fprintf('First-mode period = %.10f sec\n', period); %[output:6f32e74c]
damp = 0.02;
ops.rayleigh(2.0*damp*freq, 0.0, 0.0, 0.0);
%%
%[text] ## 16. Uniform excitation pattern
ops.pattern('UniformExcitation', 1, 1, '-accel', 1);
%%
%[text] ## 17. Transient-analysis settings
ops.wipeAnalysis();

ops.constraints('Transformation');
ops.numberer('RCM');
ops.system('UmfPack');
ops.test('EnergyIncr', 1.0e-10, 100);
ops.algorithm('KrylovNewton');
ops.integrator('Newmark', 0.5, 0.25);
ops.analysis('Transient');
%%
%[text] ## 18. Run transient analysis
nSteps = 10 * 4096;
dtAnalysis = 0.001;

ok = ops.analyze(nSteps, dtAnalysis);

if ok ~= 0 %[output:group:95ee8d98]
    warning('Transient analysis failed with return code %d.', ok);
else
    disp('Analysis completed successfully.'); %[output:3018357d]
end %[output:group:95ee8d98]
%%
%[text] ## 19. Runtime and cleanup
elapsedTime = toc;
fprintf('Total runtime = %.6f seconds\n', elapsedTime); %[output:67f05420]
ops.wipe();
%%
nodeResp = post.getNodalResponse("myODB");
linkResp = post.getElementResponse("myODB", eleType="Link");
%%
%[text] ## 20. Roof displacement comparison
%[text] The OpenSeesMatlab roof displacement is compared with the original Tcl
%[text] recorder output. The comparison is used as the first verification plot.
idx_n4 = nodeResp.nodeTags == 4;
disp_n4_opsm = nodeResp.disp.ux(:, idx_n4);

dispFile = fullfile('tcl', 'Output', 'Disp.out');
if ~exist(dispFile, 'file') %[output:group:4f874267]
    warning('Tcl reference file "%s" was not found.', dispFile);
else
    disp_n4_tcl = load(dispFile);

    disp_n4_opsm = load(fullfile(outdir, 'Disp.out'));

    fig = figure('Color', 'w', 'Position', [100, 100, 760, 420]); %[output:7d984f76]
    hold on; box on; grid on; %[output:7d984f76]

    plot(disp_n4_tcl(:, 1), disp_n4_tcl(:, 2), '-', ... %[output:7d984f76]
        'Color', [0.000, 0.250, 0.450], ... %[output:7d984f76]
        'LineWidth', 1.8); %[output:7d984f76]

    % plot(nodeResp.time, disp_n4_opsm, '--', ...
    %     'Color', [0.850, 0.100, 0.100], ...
    %     'LineWidth', 1.6);

    plot(disp_n4_opsm(:, 1), disp_n4_opsm(:, 2), '--', ... %[output:7d984f76]
        'Color', [0.850, 0.100, 0.100], ... %[output:7d984f76]
        'LineWidth', 1.6); %[output:7d984f76]

    xlabel('Time (s)', 'FontName', 'Arial', 'FontSize', 18); %[output:7d984f76]
    ylabel('Displacement (mm)', 'FontName', 'Arial', 'FontSize', 18); %[output:7d984f76]

    legend({'OpenSeesTcl', 'OpenSeesMatlab'}, ... %[output:7d984f76]
        'Location', 'northeast', ... %[output:7d984f76]
        'Interpreter', 'none', ... %[output:7d984f76]
        'FontName', 'Arial', ... %[output:7d984f76]
        'FontSize', 16, ... %[output:7d984f76]
        'Box', 'on', ... %[output:7d984f76]
        'Color', 'white', 'EdgeColor', [0.35 0.35 0.35]); %[output:7d984f76]

    styleVerificationAxes(gca); %[output:7d984f76]

    ymax = max(abs(disp_n4_tcl(:, 2)));
    ylim(1.08 * [-ymax, ymax]); %[output:7d984f76]
    xlim([min(disp_n4_tcl(:, 1)), max(disp_n4_tcl(:, 1))]); %[output:7d984f76]
    
    diffss = max(abs(disp_n4_tcl(:, 2)-disp_n4_opsm(:, 2)));
    text(gca, ... %[output:7d984f76]
        0.98, ... %[output:7d984f76]
        0.30, ... %[output:7d984f76]
        sprintf("Max. difference = %.3e ", diffss), ... %[output:7d984f76]
        "Units", "normalized", ... %[output:7d984f76]
        "HorizontalAlignment", "right", ... %[output:7d984f76]
        "VerticalAlignment", "top", ... %[output:7d984f76]
        "FontName", "Times New Roman", ... %[output:7d984f76]
        "FontSize", 16, ... %[output:7d984f76]
        "BackgroundColor", "w", ... %[output:7d984f76]
        "EdgeColor", "none", ... %[output:7d984f76]
        "Margin", 3); %[output:7d984f76]

    % exportgraphics(fig, fullfile(figDir, 'ShearFrameVD-disp.png'), 'Resolution', 300);
    exportgraphics(fig, fullfile(figDir, 'ShearFrameVD-disp.pdf'), 'ContentType', 'vector'); %[output:7d984f76]
    displacementData = table( ...
        disp_n4_tcl(:, 1), disp_n4_tcl(:, 2), ...
        disp_n4_opsm(:, 1), disp_n4_opsm(:, 2), ...
        'VariableNames', {'TclTime_s','TclDisplacement_mm', ...
        'MatlabTime_s','MatlabDisplacement_mm'});
    writetable(displacementData, ...
        fullfile(figDir, 'ShearFrameVD-disp.csv'));
    % savefig(fig, fullfile(figDir, 'ShearFrameVD-disp.fig'));
end %[output:group:4f874267]
%%
%[text] ## 21. Roof displacement--base shear comparison
%[text] The total horizontal base reaction is the sum of the reactions at the two
%[text] fixed column bases. Its sign is reversed to plot resisting base shear.

baseFile = fullfile('tcl', 'Output', 'Base.out');
baseMatlabFile = fullfile(outdir, 'Base.out');

if ~exist(baseFile, 'file') || ~exist(baseMatlabFile, 'file') %[output:group:611e672b]
    warning('Base-reaction files required for the hysteresis plot were not found.');
else
    base_tcl = load(baseFile);
    base_opsm = load(baseMatlabFile);

    baseShear_tcl = -sum(base_tcl(:, 2:end), 2);
    baseShear_opsm = -sum(base_opsm(:, 2:end), 2);
    baseEnergy_tcl = abs(trapz(disp_n4_tcl(:, 2), baseShear_tcl));
    baseEnergy_opsm = abs(trapz(disp_n4_opsm(:, 2), baseShear_opsm));
    baseEnergyDiff = abs(baseEnergy_opsm - baseEnergy_tcl);

    fig = figure('Color', 'w', 'Position', [100, 100, 620, 520]); %[output:275f6111]
    ax = axes(fig); %[output:275f6111]
    hold(ax, 'on'); box(ax, 'on'); grid(ax, 'on'); %[output:275f6111]

    plot(ax, disp_n4_tcl(:, 2), baseShear_tcl, '-', ... %[output:275f6111]
        'Color', [0.000, 0.250, 0.450], 'LineWidth', 1.6, ... %[output:275f6111]
        'DisplayName', 'OpenSeesTcl'); %[output:275f6111]
    plot(ax, disp_n4_opsm(:, 2), baseShear_opsm, '--', ... %[output:275f6111]
        'Color', [0.850, 0.100, 0.100], 'LineWidth', 1.6, ... %[output:275f6111]
        'DisplayName', 'OpenSeesMatlab'); %[output:275f6111]

    xlabel(ax, 'Roof displacement (mm)', ... %[output:275f6111]
        'FontName', 'Arial', 'FontSize', 18); %[output:275f6111]
    ylabel(ax, 'Total base shear (kN)', ... %[output:275f6111]
        'FontName', 'Arial', 'FontSize', 18); %[output:275f6111]
    legend(ax, 'Location', 'northwest', 'Interpreter', 'none', ... %[output:275f6111]
        'FontName', 'Arial', 'FontSize', 16, 'Box', 'on', ... %[output:275f6111]
        'Color', 'white', 'EdgeColor', [0.35 0.35 0.35]); %[output:275f6111]
    styleVerificationAxes(ax); %[output:275f6111]
    xline(ax, 0, ':', 'LineWidth', 0.9, 'HandleVisibility', 'off'); %[output:275f6111]
    yline(ax, 0, ':', 'LineWidth', 0.9, 'HandleVisibility', 'off'); %[output:275f6111]
    text(ax, 0.98, 0.98, ... %[output:275f6111]
        sprintf('Energy diff = %.3e J', baseEnergyDiff), ... %[output:275f6111]
        'Units', 'normalized', 'HorizontalAlignment', 'right', ... %[output:275f6111]
        'VerticalAlignment', 'top', 'Interpreter', 'none', ... %[output:275f6111]
        'FontName', 'Times New Roman', 'FontSize', 15, ... %[output:275f6111]
        'BackgroundColor', 'w', 'EdgeColor', 'none', 'Margin', 3); %[output:275f6111]

    exportgraphics(fig, fullfile(figDir, 'ShearFrameVD-base-shear.pdf'), ... %[output:275f6111]
        'ContentType', 'vector'); %[output:275f6111]
    baseShearData = table( ...
        disp_n4_tcl(:, 2), baseShear_tcl, ...
        disp_n4_opsm(:, 2), baseShear_opsm, ...
        'VariableNames', {'TclDisplacement_mm','TclBaseShear_kN', ...
        'MatlabDisplacement_mm','MatlabBaseShear_kN'});
    writetable(baseShearData, ...
        fullfile(figDir, 'ShearFrameVD-base-shear.csv'));
end %[output:group:611e672b]
%%
%[text] ## 22. Damper force--deformation comparison
%[text] The damper response is compared in force--deformation space. This checks
%[text] the nonlinear material, the twoNodeLink element response, and the sign
%[text] convention used in post-processing.

ele4_idx = linkResp.eleTags == 4;

defo_opsm = linkResp.basicDeformation.Fx(:, ele4_idx);
fo_opsm   = linkResp.basicForce.Fx(:, ele4_idx);

defoFile  = fullfile('tcl', 'Output', 'Damperdisp.out');
forceFile = fullfile('tcl', 'Output', 'Damperforce.out');

if ~exist(defoFile, 'file') || ~exist(forceFile, 'file') %[output:group:71d4cd66]
    warning('Tcl damper reference files were not found in the Output folder.');
else
    defo_tcl = load(defoFile);
    fo_tcl   = load(forceFile);

    defo_opsm = load(fullfile(outdir, 'Damperdisp.out'));
    fo_opsm   = load(fullfile(outdir, 'Damperforce.out'));

    % Damper deformation and force used in the comparison
    defo_tcl_plot = defo_tcl(:, 2);
    force_tcl_plot = -fo_tcl(:, 2);

    defo_opsm_plot = defo_opsm(:, 2);
    force_opsm_plot = -fo_opsm(:, 2);

    % Remove invalid values before integration
    valid_tcl = isfinite(defo_tcl_plot) & isfinite(force_tcl_plot);
    valid_opsm = isfinite(defo_opsm_plot) & isfinite(force_opsm_plot);

    defo_tcl_energy = defo_tcl_plot(valid_tcl);
    force_tcl_energy = force_tcl_plot(valid_tcl);

    defo_opsm_energy = defo_opsm_plot(valid_opsm);
    force_opsm_energy = force_opsm_plot(valid_opsm);

    % Dissipated energy:
    % kN * mm = J
    energy_tcl = abs(trapz(defo_tcl_energy, force_tcl_energy));
    energy_opsm = abs(trapz(defo_opsm_energy, force_opsm_energy));

    energy_diff = abs(energy_opsm - energy_tcl);

    if energy_tcl > eps
        energy_diff_percent = energy_diff / energy_tcl * 100.0;
    else
        energy_diff_percent = NaN;
    end

    % fprintf('\nDamper energy comparison\n');
    % fprintf('-----------------------------------------------\n');
    % fprintf('OpenSeesTcl dissipated energy    = %.8e J\n', energy_tcl);
    % fprintf('OpenSeesMatlab dissipated energy = %.8e J\n', energy_opsm);
    % fprintf('Absolute energy difference       = %.8e J\n', energy_diff);
    % fprintf('Relative energy difference       = %.8e %%n', ...
    %     energy_diff_percent);

    fig = figure( ... %[output:563e0249]
        'Color', 'w', ... %[output:563e0249]
        'Position', [100, 100, 620, 520]); %[output:563e0249]

    ax = axes(fig); %[output:563e0249]
    hold(ax, 'on'); %[output:563e0249]
    box(ax, 'on'); %[output:563e0249]
    grid(ax, 'on'); %[output:563e0249]

    plot(ax, ... %[output:563e0249]
        defo_tcl_plot, ... %[output:563e0249]
        force_tcl_plot, ... %[output:563e0249]
        '-', ... %[output:563e0249]
        'Color', [0.000, 0.250, 0.450], ... %[output:563e0249]
        'LineWidth', 1.6, ... %[output:563e0249]
        'DisplayName', 'OpenSeesTcl'); %[output:563e0249]

    plot(ax, ... %[output:563e0249]
        defo_opsm_plot, ... %[output:563e0249]
        force_opsm_plot, ... %[output:563e0249]
        '--', ... %[output:563e0249]
        'Color', [0.850, 0.100, 0.100], ... %[output:563e0249]
        'LineWidth', 1.6, ... %[output:563e0249]
        'DisplayName', 'OpenSeesMatlab'); %[output:563e0249]

    xlabel(ax, ... %[output:563e0249]
        'Damper deformation (mm)', ... %[output:563e0249]
        'FontName', 'Arial', ... %[output:563e0249]
        'FontSize', 18); %[output:563e0249]

    ylabel(ax, ... %[output:563e0249]
        'Damper force (kN)', ... %[output:563e0249]
        'FontName', 'Arial', ... %[output:563e0249]
        'FontSize', 18); %[output:563e0249]

    legend(ax, ... %[output:563e0249]
        'Location', 'southeast', ... %[output:563e0249]
        'Interpreter', 'none', ... %[output:563e0249]
        'FontName', 'Arial', ... %[output:563e0249]
        'FontSize', 16, ... %[output:563e0249]
        'Box', 'on', ... %[output:563e0249]
        'Color', 'white', 'EdgeColor', [0.35 0.35 0.35]); %[output:563e0249]

    styleVerificationAxes(ax); %[output:563e0249]

    xData = [defo_tcl_plot; defo_opsm_plot];
    yData = [force_tcl_plot; force_opsm_plot];

    xData = xData(isfinite(xData));
    yData = yData(isfinite(yData));

    xRange = max(xData) - min(xData);
    yRange = max(yData) - min(yData);

    if xRange > 0
        xPad = 0.08 * xRange;
        xlim(ax, [min(xData) - xPad, max(xData) + xPad]); %[output:563e0249]
    end

    if yRange > 0
        yPad = 0.2 * yRange;
        ylim(ax, [min(yData) - yPad, max(yData) + yPad]); %[output:563e0249]
    end

    xline(ax, ... %[output:563e0249]
        0, ... %[output:563e0249]
        ':', ... %[output:563e0249]
        'LineWidth', 0.9, ... %[output:563e0249]
        'HandleVisibility', 'off'); %[output:563e0249]

    yline(ax, ... %[output:563e0249]
        0, ... %[output:563e0249]
        ':', ... %[output:563e0249]
        'LineWidth', 0.9, ... %[output:563e0249]
        'HandleVisibility', 'off'); %[output:563e0249]

    % energyText = sprintf([ ...
    %     '$E_{\\mathrm{Tcl}}=%.4e\\ \\mathrm{J}$\n' ...
    %     '$E_{\\mathrm{MAT}}=%.4e\\ \\mathrm{J}$\n' ...
    %     '$\\Delta E=%.3e\\ \\mathrm{J}\\ (%.3e\\%%)$'], ...
    %     energy_tcl, ...
    %     energy_opsm, ...
    %     energy_diff, ...
    %     energy_diff_percent);
    energyText = sprintf( ...
        'Energy diff = %.3e J', ...
        energy_diff);
    
    text(ax, ... %[output:563e0249]
        0.98, 0.98, ... %[output:563e0249]
        energyText, ... %[output:563e0249]
        'Units', 'normalized', ... %[output:563e0249]
        'HorizontalAlignment', 'right', ... %[output:563e0249]
        'VerticalAlignment', 'top', ... %[output:563e0249]
        'Interpreter', 'none', ... %[output:563e0249]
        'FontName', 'Times New Roman', ... %[output:563e0249]
        'FontSize', 15, ... %[output:563e0249]
        'Color', 'k', ... %[output:563e0249]
