function styleVerificationAxes(ax)
%STYLEVERIFICATIONAXES Apply consistent formatting to verification figures.
%
% The plotting style is kept simple because the figures are intended for the
% paper and supplementary material rather than for exploratory visualization.

    set(ax, ...
        'FontName', 'Arial', ...
        'FontSize', 16, ...
        'LineWidth', 1.1, ...
        'TickDir', 'out', ...
        'GridLineStyle', '--', ...
        'GridAlpha', 0.25, ...
        'Box', 'on');
end

